$ErrorActionPreference = "Stop"

$Container = "orion-iai-m5-c"
$Payload = ""
$Loader = "import base64; exec(base64.b64decode('$Payload'))"

Write-Host "Running Phase 2 erasure-path + profile-isolation closeout..."
Write-Host "Live iai memory is read-only for this test; erasure occurs only on a disposable restore."
Write-Host ""

& docker exec `
  -u 10000:10000 `
  -e "HOME=/opt/data/profiles/companion" `
  -e "IAI_DAEMON_SOCKET_PATH=/opt/data/profiles/companion/.iai-mcp/.daemon.sock" `
  $Container `
  /opt/iai/venv/bin/python -c $Loader

if ($LASTEXITCODE -ne 0) {
    throw "Phase 2 closeout verifier failed with exit code $LASTEXITCODE"
}

Write-Host ""
Write-Host "PHASE2_CLOSEOUT_VERIFIER=PASS"
